import React, { useState, useEffect, useRef, useCallback, memo, Dispatch, SetStateAction, RefObject, ElementType, useMemo } from 'react';
import ReactDOM from 'react-dom/client';
import { 
  MessageCircle, Target, TrendingUp, Calendar, Clock, Brain, Coffee, 
  CheckCircle2, ChevronDown, ChevronUp, Code, Play, Heart, Briefcase, 
  Sparkles, Award, Flame, BookOpen, Activity, AlertCircle, X, Check, 
  Pause, Flag, ShieldCheck, Zap, HelpCircle, Paperclip, Eye, EyeOff, 
  Bell, PlusCircle, Trash2, Pencil, Plus, Leaf, Minimize2, Maximize2,
  LogOut, User, Mail, Lock
} from 'lucide-react';
import {HZ} from 'lucide-react'; 
import { GoogleGenAI, Type, FunctionDeclaration } from '@google/genai';

// --- Type Definitions ---

interface Habit {
  id: number;
  name: string;
  icon: string;
  completed: boolean;
  streak: number;
}

interface SubTask {
  id: number;
  title: string;
  completed: boolean;
}

interface CoreCircle {
  id: number;
  name: string;
  value: number;
  icon: ElementType;
  color: string;
  image?: string;
}

interface DailyScheduleItem {
  id: number;
  time: string;
  title: string;
  description?: string;
  type: string;
  completed: boolean;
  duration: number;
  isFixed: boolean;
  category?: 'worship' | 'health' | 'work' | 'learning' | 'other' | string;
  reminderMinutes?: number;
  reminderSent?: boolean;
  subTasks?: SubTask[];
}

interface MonthlyGoal {
  id: number;
  title: string;
  deadline: string;
  roadmap: { title: string; completed: boolean }[];
}

interface TaskTemplate {
    id: string;
    title: string;
    duration: number;
    type: string;
    icon: string;
    category: 'worship' | 'health' | 'work' | 'learning';
}

interface TaskCategory {
    id: string;
    name: string;
    icon: ElementType;
    tasks: TaskTemplate[];
    image?: string;
}

interface UserProfile {
  id: string;
  email: string;
  name: string;
  goals: any[];
  wakeTime: string;
  sleepTime: string;
}

interface Achievement {
  id: string;
  title: string;
  description: string;
  icon: ElementType;
  unlocked: boolean;
}

interface Message {
  role: 'user' | 'ai';
  text: string;
  timestamp: Date;
  attachment?: string;
}

interface SuggestedTask {
  id: string;
  title: string;
  time: string;
  duration: number;
  category?: string;
  subTasks?: { title: string; completed: boolean }[];
}

interface ReviewResult {
  type: 'success' | 'error';
  message: string;
  score?: number;
  errors?: { line: number; message: string; severity: 'error' | 'warning' }[];
  suggestions?: string[];
}

// --- Props Interfaces ---

interface DailyViewProps {
  currentTime: Date;
  stats: { streak: number; points: number; };
  dailySchedule: DailyScheduleItem[];
  toggleScheduleItem: (id: number) => void;
  deleteScheduleItem: (id: number) => void;
  toggleSubTask: (taskId: number, subTaskId: number) => void;
  activePomodoroTask: DailyScheduleItem | null;
  startPomodoro: (task: DailyScheduleItem) => void;
  showCompletedTasks: boolean;
  setShowCompletedTasks: Dispatch<SetStateAction<boolean>>;
  queryTaskDetails: (task: DailyScheduleItem) => Promise<void>;
  taskCategories: TaskCategory[];
  handleAddTaskFromTemplate: (task: TaskTemplate) => void;
  setReminderTask: Dispatch<SetStateAction<DailyScheduleItem | null>>;
  onAddTask: () => void;
  onEditTask: (task: DailyScheduleItem) => void;
}

interface ChatViewProps {
  messages: Message[];
  suggestedTasks: SuggestedTask[];
  confirmTask: (taskId: string) => void;
  confirmAllTasks: () => void;
  rejectTask: (taskId: string) => void;
  rejectAllTasks: () => void;
  isLoading: boolean;
  chatEndRef: RefObject<HTMLDivElement | null>;
  inputRef: RefObject<HTMLTextAreaElement | null>;
  inputMessage: string;
  setInputMessage: Dispatch<SetStateAction<string>>;
  handleSendMessage: (messageToSend?: string) => Promise<void>;
  attachedFile: { data: string; mimeType: string; } | null;
  setAttachedFile: Dispatch<SetStateAction<{ data: string; mimeType: string; } | null>>;
}

interface ReviewViewProps {
  codeToReview: string;
  setCodeToReview: Dispatch<SetStateAction<string>>;
  reviewCode: () => Promise<void>;
  isLoading: boolean;
  reviewResult: ReviewResult | null;
}

interface GoalsViewProps {
  monthlyGoals: MonthlyGoal[];
  isLoading: boolean;
  generateLongTermGoals: () => Promise<void>;
  toggleGoalStep: (goalId: number, stepIndex: number) => void;
  deleteGoal: (goalId: number) => void;
}

interface ProgressViewProps {
  userProfile: UserProfile;
  stats: { points: number; streak: number };
  dailySchedule: DailyScheduleItem[];
  achievements: Achievement[];
  onSignOut: () => void;
}

interface AuthViewProps {
  onLogin: (profile: UserProfile) => void;
  addNotification: (message: string, type?: string) => void;
}

interface PomodoroTimerProps {
  activePomodoroTask: DailyScheduleItem | null;
  pomodoroPhase: 'work' | 'break';
  pomodoroTimeLeft: number;
  isPomodoroRunning: boolean;
  pomodoroSessions: number;
  formatPomodoroTime: (seconds: number) => string;
  togglePomodoro: () => void;
  stopPomodoro: () => void;
}

// --- Helpers ---

const formatTo12Hour = (timeString: string): string => {
  if (!timeString || !timeString.includes(':')) return timeString;
  const [hour, minute] = timeString.split(':').map(Number);
  const ampm = hour >= 12 ? 'م' : 'ص';
  let hour12 = hour % 12;
  if (hour12 === 0) hour12 = 12;
  return `${hour12.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')} ${ampm}`;
};

// --- Sub-Components ---

const CoreHabitsView = memo(({ categories, onAddTask }: { categories: TaskCategory[]; onAddTask: (task: TaskTemplate) => void; }) => {
    const [openCategory, setOpenCategory] = useState<string | null>(null);

    return (
        <div className="space-y-4 mt-8">
            <h3 className="text-xl font-serif font-bold text-white flex items-center gap-2 mb-4 px-2">
                <Zap className="w-5 h-5 text-yellow-400" />
                عادات أساسية
            </h3>
            <div className="grid grid-cols-1 gap-4">
            {categories.map(category => {
                const Icon = category.icon;
                const isOpen = openCategory === category.id;

                return (
                    <div key={category.id} className="rounded-2xl overflow-hiddenHJ border border-white/10 relative group transition-all duration-300 hover:shadow-lg hover:shadow-purple-500/20">
                        <div className="absolute inset-0 z-0">
                           {category.image && <img src={category.image} alt={category.name} className="w-full h-full object-cover opacity-50 group-hover:opacity-60 transition-opacity filter brightness-75" />}
                           <div className="absolute inset-0 bg-gradient-to-r from-[#0f0c29] via-[#0f0c29]/90 to-transparent"></div>
                        </div>

                        <div className="relative z-10">
                            <button
                                onClick={() => setOpenCategory(isOpen ? null : category.id)}
                                className="w-full p-5 flex items-center justify-between text-white transition-colors"
                            >
                                <div className="flex items-center gap-4">
                                    <div className="p-3 bg-white/10 backdrop-blur-md rounded-xl border border-white/20 shadow-inner">
                                       <Icon className="w-6 h-6 text-white drop-shadow-md" />
                                    </div>
                                    <span className="font-serif text-xl font-bold">{category.name}</span>
                                </div>
                                <div className={`p-2 rounded-full bg-white/5 backdrop-blur-sm transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`}>
                                     <ChevronDown className="w-5 h-5 text-white" />
                                </div>
                            </button>

                            {isOpen && (
                                <div className="p-5 pt-0 animate-slide-in">
                                    <div className="grid grid-cols-1 gap-3">
                                        {category.tasks.map(task => (
                                            <div key={task.id} className="flex items-center gap-3 p-3 bg-black/40 backdrop-blur-md rounded-xl border border-white/10 hover:bg-white/10 transition-colors">
                                                <span className="text-2xl filter drop-shadow-sm">{task.icon}</span>
                                                <div className="flex-1">
                                                    <p className="font-serif font-medium text-white">{task.title}</p>
                                                    <p className="text-xs text-gray-400">{task.duration} دقيقة</p>
                                                </div>
                                                <button 
                                                    onClick={() => onAddTask(task)}
                                                    className="p-2 text-gray-300 hover:text-white bg-white/5 hover:bg-purple-500 rounded-full transition-all"
                                                >
                                                    <PlusCircle className="w-5 h-5" />
                                                </button>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                );
            })}
            </div>
        </div>
    );
});

const DailyView = memo(({
  currentTime,
  stats,
  dailySchedule,
  toggleScheduleItem,
  deleteScheduleItem,
  toggleSubTask,
  activePomodoroTask,
  startPomodoro,
  showCompletedTasks,
  setShowCompletedTasks,
  queryTaskDetails,
  taskCategories,
  handleAddTaskFromTemplate,
  setReminderTask,
  onAddTask,
  onEditTask,
}: DailyViewProps) => {
    const [expandedTasks, setExpandedTasks] = useState<Set<number>>(new Set());

    const toggleExpand = (id: number) => {
        setExpandedTasks(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    };

    return (
    <div className="relative h-full overflow-y-auto pb-28 no-scrollbar">
