To link your project with Supabase, I will update the application to replace the local storage logic with real backend calls using the Supabase Client.

**Required Action:**
You **MUST** run the following SQL script in your Supabase project's **SQL Editor** to create the necessary tables for the app to work. Without this, the app will encounter errors.

```sql
-- Create Profiles Table
create table profiles (
  id uuid references auth.users not null primary key,
  name text,
  wake_time text,
  sleep_time text,
  points int default 0,
  streak int default 0
);

-- Create Tasks Table
create table tasks (
  id bigint generated by default as identity primary key,
  user_id uuid references auth.users not null,
  title text not null,
  time text,
  duration int,
  type text,
  category text,
  completed boolean default false,
  is_fixed boolean default false,
  reminder_minutes int,
  sub_tasks jsonb default '[]'::jsonb,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- Create Goals Table
create table goals (
  id bigint generated by default as identity primary key,
  user_id uuid references auth.users not null,
  title text not null,
  deadline text,
  roadmap jsonb default '[]'::jsonb,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- Create Chat Logs Table
create table chat_logs (
  id bigint generated by default as identity primary key,
