const AuthView = memo(({ onLogin, addNotification }: AuthViewProps) => {
    const [isSignUp, setIsSignUp] = useState(false);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [name, setName] = useState('');
    const [wakeTime, setWakeTime] = useState('07:00');
    const [sleepTime, setSleepTime] = useState('23:00');
    const [isLoading, setIsLoading] = useState(false);

    const handleAuth = async () => {
        if (!email || !password) {
            addNotification("من فضلك أدخل البريد الإلكتروني وكلمة المرور", "warning");
            return;
        }

        setIsLoading(true);

        try {
            if (isSignUp) {
                if (!name) {
                     addNotification("من فضلك أدخل اسمك", "warning");
                     setIsLoading(false);
                     return;
                }

                const { data, error } = await supabase.auth.signUp({
                    email,
                    password,
                    options: {
                        data: {
                            name,
                            wake_time: wakeTime,
                            sleep_time: sleepTime
                        }
                    }
                });

                if (error) throw error;

                // Manually insert profile if trigger doesn't exist (safety fallback)
                if (data.user) {
                    await supabase.from('profiles').upsert({
                        id: data.user.id,
                        name,
                        wake_time: wakeTime,
                        sleep_time: sleepTime
                    });
                }

                addNotification("تم إنشاء الحساب بنجاح! 🚀", "success");
            } else {
                const { error } = await supabase.auth.signInWithPassword({
                    email,
                    password
                });
                if (error) throw error;
                addNotification("مرحباً بعودتك! 👋", "success");
            }
            onLogin(); // Trigger parent refresh
        } catch (error: any) {
            addNotification(error.message || "حدث خطأ ما", "error");
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-[#0f0c29]">
             <div className="absolute inset-0 bg-[url('https://images.unsplash.com/photo-1519681393798-3828fb4090bb?q=80&w=2940')] bg-cover opacity-20"></div>
             <div className="glass-card w-full max-w-md p-8 rounded-[2.5rem] border border-white/10 relative shadow-2xl animate-in zoom-in duration-300">
                <div className="text-center mb-8">
                     <div className="w-16 h-16 bg-gradient-to-br from-purple-600 to-blue-600 rounded-2xl mx-auto flex items-center justify-center shadow-lg transform rotate-3 mb-4">
                         <Brain className="w-8 h-8 text-white" />
                     </div>
                     <h2 className="text-3xl font-serif font-bold text-white mb-2">{isSignUp ? 'حساب جديد' : 'تسجيل الدخول'}</h2>
                     <p className="text-gray-400 font-serif text-sm">ابدأ رحلتك نحو الإنتاجية والتركيز</p>
                </div>

                <div className="space-y-4">
                    {isSignUp && (
                        <div className="relative">
