                <div className="text-center mb-8">
                     <div className="w-16 h-16 bg-gradient-to-br from-purple-600 to-blue-600 rounded-2xl mx-auto flex items-center justify-center shadow-lg transform rotate-3 mb-4">
                         <Brain className="w-8 h-8 text-white" />
                     </div>
                     <h2 className="text-3xl font-serif font-bold text-white mb-2">{isSignUp ? 'حساب جديد' : 'تسجيل الدخول'}</h2>
                     <p className="text-gray-400 font-serif text-sm">ابدأ رحلتك نحو الإنتاجية والتركيز</p>
                </div>

                <div className="space-y-4">
                    {isSignUp && (
                        <div className="relative">
                            <User className="absolute top-1/2 -translate-y-1/2 right-4 w-5 h-5 text-gray-400" />
                            <input 
                                type="text" 
                                placeholder="الاسم" 
                                value={name}
                                onChange={e => setName(e.target.value)}
                                className="w-full bg-black/30 border border-white/20 rounded-xl p-4 pr-12 text-white placeholder-gray-500 focus:border-purple-500 outline-none transition-all"
                            />
                        </div>
                    )}

                    <div className="relative">
                        <Mail className="absolute top-1/2 -translate-y-1/2 right-4 w-5 h-5 text-gray-400" />
                         <input 
                            type="email" 
                            placeholder="البريد الإلكتروني" 
                            value={email}
                            onChange={e => setEmail(e.target.value)}
                            className="w-full bg-black/30 border border-white/20 rounded-xl p-4 pr-12 text-white placeholder-gray-500 focus:border-purple-500 outline-none transition-all"
                        />
                    </div>

                    <div className="relative">
                        <Lock className="absolute top-1/2 -translate-y-1/2 right-4 w-5 h-5 text-gray-400" />
                         <input 
