export async function fetchMessages(sessionId: string) {
  const { data, error } = await supabase
    .from('messages')
    .select('role, content')
    .eq('session_id', sessionId)
    .order('created_at', { ascending: true })
    .limit(15)

  if (error) throw error
  return data
}

