export function buildPrompt(profile: any, messages: any[]) {
  const systemContext = `
اسم المستخدم: ${profile.name}
ميعاد الصحيان: ${profile.wake_time}
ميعاد النوم: ${profile.sleep_time}

التزم إن اقتراحاتك تناسب نظام يوم المستخدم.
  `

  return [
    { role: 'system', content: systemContext },
    ...messages
  ]
}

