const PomodoroTimer = memo(({
    activePomodoroTask,
    pomodoroPhase,
    pomodoroTimeLeft,
    isPomodoroRunning,
    pomodoroSessions,
    formatPomodoroTime,
    togglePomodoro,
    stopPomodoro,
}: PomodoroTimerProps) => {
    const [isMinimized, setIsMinimized] = useState(false);

    if (!activePomodoroTask) return null;

    const totalDuration = pomodoroPhase === 'work' 
        ? activePomodoroTask.duration * 60
        : (pomodoroSessions % 4 === 0 ? 15 * 60 : 5 * 60);

    const progress = totalDuration > 0 ? (pomodoroTimeLeft / totalDuration) * 100 : 0;

    if (isMinimized) {
        return (
            <div className="fixed bottom-24 right-4 z-[999] animate-in fade-in slide-in-from-bottom-4">
                <div className="glass-card p-3 rounded-2xl border border-white/20 shadow-2xl flex items-center gap-3 backdrop-blur-xl bg-black/80">
                     <div className="relative w-10 h-10 flex items-center justify-center">
                        <svg className="absolute inset-0 w-full h-full -rotate-90" viewBox="0 0 36 36">
                            <path className="text-gray-700" d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" fill="none" stroke="currentColor" strokeWidth="4" />
                            <path className={`${pomodoroPhase === 'work' ? 'text-purple-500' : 'text-green-500'}`} strokeDasharray={`${progress}, 100`} d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" fill="none" stroke="currentColor" strokeWidth="4" />
                        </svg>
                        <button onClick={togglePomodoro} className="absolute inset-0 flex items-center justify-center">
                             {isPomodoroRunning ? <Pause className="w-4 h-4 fill-white text-white" /> : <Play className="w-4 h-4 fill-white text-white ml-0.5" />}
                        </button>
                     </div>
                     <div className="flex flex-col">
                         <span className="font-mono font-bold text-white text-lg leading-none">{formatPomodoroTime(pomodoroTimeLeft)}</span>
                         <span className="text-[10px] text-gray-400 max-w-[80px] truncate">{activePomodoroTask.title}</span>
                     </div>
                     <button onClick={() => setIsMinimized(false)} className="p-1.5 hover:bg-white/10 rounded-full transition-colors">
                        <Maximize2 className="w-4 h-4 text-gray-400 hover:text-white" />
                     </button>
                </div>
            </div>
        );
    }

    return (
        <div className="fixed inset-0 z-[999] flex flex-col items-center justify-center bg-[#0f0c29] text-white animate-in fade-in">
             <div className="absolute inset-0 z-0">
                  <img src="https://i.pinimg.com/736x/b2/20/bc/b220bcbe9b790c63024e2578b5605e8f.jpg" alt="Focus" className="w-full h-full object-cover filter brightness-50 opacity-60" />
                  <div className="absolute inset-0 bg-gradient-to-b from-[#0f0c29] via-transparent to-[#0f0c29]"></div>
             </div>

             <div className="absolute top-6 right-6 z-20">
                <button onClick={() => setIsMinimized(true)} className="p-3 bg-white/10 rounded-full hover:bg-white/20 backdrop-blur-md transition-all">
                    <Minimize2 className="w-6 h-6 text-white" />
                </button>
             </div>

             <div className="relative z-10 flex flex-col items-center w-full max-w-md p-6">
                <div className="glass-panel px-4 py-1.5 rounded-full text-sm font-bold flex items-center gap-2 bg-white/10 backdrop-blur-md border-white/20 mb-8">
                      {pomodoroPhase === 'work' ? <Flame className="w-4 h-4 text-orange-400" /> : <Coffee className="w-4 h-4 text-green-400" />}
                      <span className="font-serif">{pomodoroPhase === 'work' ? 'وقت التركيز' : 'وقت الاستراحة'}</span>
                </div>

                <h2 className="text-3xl font-serif font-bold text-center mb-2 drop-shadow-md">{activePomodoroTask.title}</h2>
                <div className="flex gap-1 mb-10">
                     {Array.from({ length: 4 }).map((_, i) => (
                        <div key={i} className={`w-2 h-2 rounded-full ${i < pomodoroSessions ? 'bg-purple-400' : 'bg-gray-600'}`}></div>
                     ))}
                </div>

                <div className="text-[6rem] font-mono font-bold tracking-tighter leading-none mb-8 drop-shadow-[0_0_15px_rgba(255,255,255,0.3)]">
                     {formatPomodoroTime(pomodoroTimeLeft)}
                </div>

                <div className="w-64 h-2 bg-white/10 rounded-full overflow-hidden mb-12">
                    <div 
                        className={`h-full transition-all duration-1000 ease-linear ${pomodoroPhase === 'work' ? 'bg-gradient-to-r from-purple-500 to-pink-500' : 'bg-gradient-to-r from-green-400 to-emerald-500'}`}
                        style={{ width: `${progress}%` }}
                    ></div>
                </div>

                <div className="flex items-center gap-6">
                    <button onClick={togglePomodoro} className="w-20 h-20 rounded-full bg-white text-black flex items-center justify-center hover:scale-105 transition-transform shadow-[0_0_30px_rgba(255,255,255,0.3)]">
                        {isPomodoroRunning ? <Pause className="w-8 h-8 fill-black" /> : <Play className="w-8 h-8 fill-black ms-1" />}
                    </button>
                    <button onClick={stopPomodoro} className="w-14 h-14 rounded-full bg-white/10 border border-white/20 flex items-center justify-center hover:bg-red-500/20 hover:border-red-500/50 transition-colors">
                        <X className="w-6 h-6" />
                    </button>
                </div>
             </div>
        </div>
    );
});

const TaskModal = memo(({ task, onSave, onCancel }: { task: DailyScheduleItem | null; onSave: (task: DailyScheduleItem) => void; onCancel: () => void; }) => {
    if (!task) return null;
    const [taskData, setTaskData] = useState<DailyScheduleItem>(task);
    const [newSubTask, setNewSubTask] = useState('');
    const [isGenerating, setIsGenerating] = useState(false);
    const aiClient = useRef<GoogleGenAI | null>(null);

    useEffect(() => { 
        setTaskData(task); 
        aiClient.current = new GoogleGenAI({ apiKey: process.env.API_KEY });
    }, [task]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setTaskData(prev => ({ ...prev, [name]: name === 'duration' ? Number(value) : value }));
    };

    const addSubTask = () => {
        if(!newSubTask.trim()) return;
        setTaskData(prev => ({ ...prev, subTasks: [...(prev.subTasks || []), { id: Date.now(), title: newSubTask, completed: false }] }));
        setNewSubTask('');
    };

    const generateSubtasks = async () => {
        if(!taskData.title || !aiClient.current) return;
        setIsGenerating(true);
        try {
            const prompt = `Break down the task "${taskData.title}" into 3-5 concise, actionable sub-steps. Return JSON array: [{title: "Step 1", completed: false}, ...]`;
            const result = await aiClient.current.models.generateContent({
                model: 'gemini-2.5-flash',
                contents: prompt,
                config: { responseMimeType: 'application/json' }
            });
            const steps = JSON.parse(result.text || '[]');
            const newSteps = steps.map((s: any, i: number) => ({ ...s, id: Date.now() + i }));
            setTaskData(prev => ({ ...prev, subTasks: [...(prev.subTasks || []), ...newSteps] }));
        } catch (e) {
            console.error(e);
        } finally {
            setIsGenerating(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
            <div className="glass-card w-full max-w-md p-6 rounded-3xl border border-white/10 relative">
                <h3 className="text-xl font-bold font-serif text-white mb-4">{task.id === 0 ? 'إضافة مهمة' : 'تعديل المهمة'}</h3>
                <div className="space-y-4">
                    <input type="text" name="title" value={taskData.title} onChange={handleChange} placeholder="عنوان المهمة" className="w-full bg-black/30 border border-white/10 rounded-xl p-3 text-white focus:border-purple-500 outline-none" />
                    <div className="grid grid-cols-2 gap-4">
                        <input type="time" name="time" value={taskData.time} onChange={handleChange} className="w-full bg-black/30 border border-white/10 rounded-xl p-3 text-white focus:border-purple-500 outline-none text-center" />
                        <input type="number" name="duration" value={taskData.duration} onChange={handleChange} placeholder="المدة (د)" className="w-full bg-black/30 border border-white/10 rounded-xl p-3 text-white focus:border-purple-500 outline-none text-center" />
                    </div>
                     <select name="category" value={taskData.category} onChange={handleChange} className="w-full bg-black/30 border border-white/10 rounded-xl p-3 text-white focus:border-purple-500 outline-none">
                        <option value="work">عمل</option>
                        <option value="learning">تعلم</option>
                        <option value="health">صحة</option>
                        <option value="worship">عبادة</option>
                        <option value="other">أخرى</option>
                    </select>
                    <div>
                        <div className="flex justify-between items-center mb-2">
                            <span className="text-sm text-gray-400">الخطوات الفرعية</span>
                            <button onClick={generateSubtasks} disabled={isGenerating || !taskData.title} className="text-xs text-purple-300 flex items-center gap-1 hover:text-white disabled:opacity-50">
                                {isGenerating ? <Activity className="w-3 h-3 animate-spin" /> : <Sparkles className="w-3 h-3" />}
                                <span>توليد خطوات بالذكاء الاصطناعي</span>
                            </button>
                        </div>
                        <div className="flex gap-2 mb-2">
                             <input type="text" value={newSubTask} onChange={e => setNewSubTask(e.target.value)} placeholder="خطوة فرعية..." className="flex-1 bg-black/30 border border-white/10 rounded-xl p-2 text-sm text-white focus:border-purple-500 outline-none" />
                             <button onClick={addSubTask} className="p-2 bg-purple-600 rounded-xl"><Plus className="w-4 h-4 text-white" /></button>
                        </div>
                        <div className="max-h-32 overflow-y-auto space-y-1">
                             {taskData.subTasks?.map(st => (
                                 <div key={st.id} className="flex justify-between items-center p-2 bg-white/5 rounded-lg">
                                     <span className="text-sm text-gray-300">{st.title}</span>
                                     <button onClick={() => setTaskData(prev => ({...prev, subTasks: prev.subTasks?.filter(s => s.id !== st.id)}))} className="text-red-400"><X className="w-3 h-3" /></button>
                                 </div>
                             ))}
                        </div>
                    </div>
                </div>
                <div className="flex gap-3 mt-6">
                    <button onClick={onCancel} className="flex-1 py-3 bg-white/5 hover:bg-white/10 rounded-xl text-gray-300">إلغاء</button>
                    <button onClick={() => onSave(taskData)} className="flex-1 py-3 bg-gradient-to-r from-purple-600 to-pink-600 rounded-xl text-white font-bold shadow-lg">حفظ</button>
                </div>
            </div>
        </div>
    );
});

